<?php
namespace Support\Component\Supportplans\Administrator\Controller;
\defined('_JEXEC') or die;
use Joomla\CMS\Factory;
use Joomla\CMS\MVC\Controller\BaseController;
use Joomla\CMS\Router\Route;
use Joomla\CMS\Session\Session;
class PlanController extends BaseController
{
    private function nextSequence($db): int { $q=$db->getQuery(true)->select('COALESCE(MAX('.$db->quoteName('sequence_no').'),0)+1')->from($db->quoteName('#__supportplans_plans')); return (int)$db->setQuery($q)->loadResult(); }
    private function resequence($db): void { $q=$db->getQuery(true)->select('id')->from($db->quoteName('#__supportplans_plans'))->order('sequence_no ASC,id ASC'); $ids=$db->setQuery($q)->loadColumn(); $n=1; foreach($ids as $id){$q=$db->getQuery(true)->update($db->quoteName('#__supportplans_plans'))->set('sequence_no='.(int)$n)->where('id='.(int)$id);$db->setQuery($q)->execute();$n++;}}
    private function getServicePlan($db,int $id): ?object { if($id<1)return null; $q=$db->getQuery(true)->select('*')->from($db->quoteName('#__supportplans_serviceplans'))->where('id='.(int)$id); return $db->setQuery($q)->loadObject(); }
    public function add(): void { Factory::getApplication()->redirect(Route::_('index.php?option=com_supportplans&view=plans&tmpl=component&mode=new&Itemid=785',false)); }
    public function cancel(): void { Factory::getApplication()->redirect(Route::_('index.php?option=com_supportplans&view=plans&tmpl=component&Itemid=785',false)); }
    public function apply(): void{$this->store('apply');} public function save():void{$this->store('close');} public function save2new():void{$this->store('new');} public function update():void{$this->store('apply');}
    private function store(string $after):void
    {
        Session::checkToken() or jexit('Invalid Token'); $app=Factory::getApplication();$in=$app->input;$db=Factory::getContainer()->get('DatabaseDriver');$id=$in->getInt('id');$customer=trim($in->getString('customer_name'));$serviceId=$in->getInt('service_plan_id');
        if($customer===''){ $app->enqueueMessage('Συμπληρώστε το όνομα πελάτη.','error');$app->redirect(Route::_($id?'index.php?option=com_supportplans&view=plans&tmpl=component&plan_id=&Itemid=785'.$id:'index.php?option=com_supportplans&view=plans&tmpl=component&mode=new&Itemid=785',false));return; }
        $service=$this->getServicePlan($db,$serviceId); if(!$service){$app->enqueueMessage('Επιλέξτε πλάνο υποστήριξης.','error');$app->redirect(Route::_($id?'index.php?option=com_supportplans&view=plans&tmpl=component&plan_id=&Itemid=785'.$id:'index.php?option=com_supportplans&view=plans&tmpl=component&mode=new&Itemid=785',false));return;}
        $purchase=$in->getString('purchase_date',date('Y-m-d'));$status=$in->getCmd('status','active')==='completed'?'completed':'active';
        if($id>0){
            $q=$db->getQuery(true)->select('service_plan_id')->from($db->quoteName('#__supportplans_plans'))->where('id='.(int)$id);$oldService=(int)$db->setQuery($q)->loadResult();
            $fields=[$db->quoteName('customer_name').'='.$db->quote($customer),$db->quoteName('supported_websites').'='.$db->quote(trim($in->getString('supported_websites'))),$db->quoteName('form_number').'='.$db->quote(trim($in->getString('form_number'))),$db->quoteName('purchase_date').'='.$db->quote($purchase),$db->quoteName('vat_rate').'='.(float)$in->getFloat('vat_rate',24),$db->quoteName('status').'='.$db->quote($status),$db->quoteName('service_plan_id').'='.(int)$serviceId];
            if($oldService!==$serviceId){$mode=in_array(($service->billing_mode??'prepaid'),['ongoing','subscription'],true)?$service->billing_mode:'prepaid';$rate=$mode==='ongoing'?(float)$service->hourly_rate:($service->total_minutes?((float)$service->total_cost/((int)$service->total_minutes/60)):0);$fields=array_merge($fields,[$db->quoteName('plan_type').'='.$db->quote($service->name),$db->quoteName('billing_mode').'='.$db->quote($mode),$db->quoteName('subscription_months').'='.(int)($service->subscription_months??1),$db->quoteName('initial_minutes').'='.(int)$service->total_minutes,$db->quoteName('initial_amount').'='.(float)$service->total_cost,$db->quoteName('hourly_rate').'='.(float)$rate,$db->quoteName('min_minutes').'='.(int)$service->min_minutes,$db->quoteName('step_minutes').'='.(int)$service->step_minutes,$db->quoteName('plan_description').'='.$db->quote((string)$service->description)]);}
            $q=$db->getQuery(true)->update($db->quoteName('#__supportplans_plans'))->set($fields)->where('id='.(int)$id);$db->setQuery($q)->execute();$app->enqueueMessage('Το πακέτο αποθηκεύτηκε.');
        } else {
            $mode=in_array(($service->billing_mode??'prepaid'),['ongoing','subscription'],true)?$service->billing_mode:'prepaid';$rate=$mode==='ongoing'?(float)$service->hourly_rate:($service->total_minutes?((float)$service->total_cost/((int)$service->total_minutes/60)):0);$cols=['sequence_no','customer_name','supported_websites','form_number','service_plan_id','plan_type','billing_mode','subscription_months','purchase_date','initial_minutes','hourly_rate','initial_amount','min_minutes','step_minutes','plan_description','vat_rate','status','created'];
            $vals=[$this->nextSequence($db),$db->quote($customer),$db->quote(trim($in->getString('supported_websites'))),$db->quote(trim($in->getString('form_number'))),(int)$serviceId,$db->quote($service->name),$db->quote($mode),(int)($service->subscription_months??1),$db->quote($purchase),(int)$service->total_minutes,(float)$rate,(float)$service->total_cost,(int)$service->min_minutes,(int)$service->step_minutes,$db->quote((string)$service->description),(float)$in->getFloat('vat_rate',24),$db->quote($status),$db->quote(Factory::getDate()->toSql())];
            $q=$db->getQuery(true)->insert($db->quoteName('#__supportplans_plans'))->columns($db->quoteName($cols))->values(implode(',',$vals));$db->setQuery($q)->execute();$id=(int)$db->insertid();$app->enqueueMessage('Το νέο πακέτο δημιουργήθηκε.');
        }
        if($after==='close'){$app->redirect(Route::_('index.php?option=com_supportplans&view=plans&tmpl=component&Itemid=785',false));return;}if($after==='new'){$app->redirect(Route::_('index.php?option=com_supportplans&view=plans&tmpl=component&mode=new&Itemid=785',false));return;}$app->redirect(Route::_('index.php?option=com_supportplans&view=plans&tmpl=component&plan_id=&Itemid=785'.$id,false));
    }
    public function delete():void{Session::checkToken() or jexit('Invalid Token');$app=Factory::getApplication();$db=Factory::getContainer()->get('DatabaseDriver');$id=$app->input->getInt('id');if($id>0){$db->transactionStart();try{$q=$db->getQuery(true)->delete($db->quoteName('#__supportplans_entries'))->where('plan_id='.(int)$id);$db->setQuery($q)->execute();$q=$db->getQuery(true)->delete($db->quoteName('#__supportplans_plans'))->where('id='.(int)$id);$db->setQuery($q)->execute();$this->resequence($db);$db->transactionCommit();$app->enqueueMessage('Το πακέτο διαγράφηκε.');}catch(\Throwable $e){$db->transactionRollback();throw $e;}}$app->redirect(Route::_('index.php?option=com_supportplans&view=plans&tmpl=component&Itemid=785',false));}
}
